/**
 * lib/ws.mjs —— 工作区目录名 → 真实路径（与根藏/寻枝同一实现）
 *
 * 为什么要单独一份：共享抽取库不能依赖根藏的 paths.mjs（那会把它重新绑回根藏）。
 * 行为必须与 root/lib/paths.mjs 的 prettyWorkspace 一致；改动需两边同步并跑
 * tools/check-utterance-core.mjs 的行为对账。
 */
export function prettyWorkspace(dirName) {
  let s = String(dirName || '')
  s = s.replace(/^--+/, '').replace(/-+$/, '')
  s = s.replace(/~([0-9A-Fa-f]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
  const m = /^([A-Za-z])-(.*)$/.exec(s)
  if (m) return `${m[1].toUpperCase()}:\\${m[2].replace(/-/g, '\\')}`
  return s.replace(/-/g, '\\')
}
